    throw Error('TASK_HEALTH_NOT_TESTED')
  const eventSha256 = sha(plainFile(eventPath))
  const path = join(control, 'publication-admission', m.id, eventSha256 + '.json')
  if (!existsSync(path)) throw Error('ADMISSION_MISSING')
