  const required = a.requiredChecks
  if (
    !Array.isArray(required) ||
    !required.length ||
    required.some((id) => typeof id !== 'string' || !/^[a-z][a-z0-9-]{0,63}$/.test(id)) ||
    new Set(required).size !== required.length
