    admission.schemaVersion !== 1 ||
    admission.id !== m.id ||
    admission.kind !== e.kind ||
    admission.task !== (e.kind === 'TASK' ? e.task : null) ||
    admission.sourceHead !== head ||
    admission.manifestSha256 !== sha(plainFile(manifestPath)) ||
